 Map
  WEB
    METADATA
      "wms_enable_request" "*"
      "wms_title"            "THEMIS Footprints"
      "wms_onlineresource"   "/redace_map/themis?"
      "wms_srs"              "EPSG:4326"

      "ows_enable_request"   "*"
      "ows_title"            "THEMIS Footprints"
      "ows_onlineresource"   "/redace_map/themis?"
      "ows_srs"              "EPSG:4326"
    End
  END

#for skelton background
  IMAGETYPE      PNG24
  TRANSPARENT    ON
  OUTPUTFORMAT
    NAME png24
    DRIVER "GD/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGBA
    EXTENSION "png"
  END

  PROJECTION
    "init=epsg:4326"
  END

  EXTENT -180 -90 180 90
  UNITS DD

  LAYER
    NAME "themis"
    SIZEUNITS pixels
    STATUS on 

    METADATA
      "wms_title"  "THEMIS Footprints"
      "wms_srs"    "EPSG:4326"
      "wms_extent" "-180 -90 180 90"
    END

    METADATA
      "ows_title"  "THEMIS Footprints"
      "ows_srs"    "EPSG:4326"
      "ows_extent" "-180 -90 180 90"
    END

    CONNECTIONTYPE postgis
    CONNECTION "user=ta282ji password=triathlon dbname=mars host=172.16.238.5"


    PROCESSING "CLOSE_CONNECTION=DEFER"    
    DATA "footprint FROM themis" 
    TYPE POLYGON
    CLASS
      STYLE
       ANTIALIAS true 
        COLOR 255 0 255
      END
    END
  END
END
